import type { Question } from '../questions';

export const UPPSC_PCS_2025_PRELIMS_GS_2_CSAT_FULL_1: Question[] = [
  { id: 'b15-001-csat-q001', section: 'General Studies II (CSAT)', topic: 'Data sufficiency', difficulty: 'hard', question: 'In a block-level planning exercise, What is the value of x? Statement I: x + y = 12. Statement II: y = 5. Treat every condition in the case as binding.', options: ['Even both statements together are insufficient.', 'Statement I alone is sufficient.', 'Statement II alone is sufficient.', 'Both statements together are sufficient, but neither alone is sufficient.'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'I alone leaves two unknowns; II alone gives only y. Together, x=12−5=7.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q002', section: 'General Studies II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'An emergency-service office compared average response times across two zones. The hill zone appeared slower, but it also had longer travel distances, steeper roads and fewer all-weather routes. The office adjusted for those operating differences before evaluating the teams.\n\nWhich principle is illustrated most clearly?', options: ['A zone with fewer calls must always be slower.', 'Geography cannot influence response time.', 'Raw average response time is sufficient in every comparison.', 'Performance comparisons should control for relevant differences in operating conditions.'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The office avoided attributing the raw response-time difference to team performance until relevant operating conditions were taken into account.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q003', section: 'General Studies II (CSAT)', topic: 'Simple interest', difficulty: 'easy', question: 'A district coordination team records the following situation. A cooperative deposits ₹5500 at simple interest of 10% per year for 3 years. How much interest is earned? Use the stated quantities exactly; no outside assumption is needed.', options: ['7150', '550', '1650', '1820.5'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Simple interest = PRT/100 = 5500×10×3/100 = ₹1650.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q004', section: 'General Studies II (CSAT)', topic: 'Hindi comprehension', difficulty: 'medium', question: 'For a local-service decision note, एक ग्राम पुस्तकालय ने शाम का समय एक घंटा बढ़ाया। पहले कई मजदूर काम से लौटने तक पुस्तकालय बंद हो जाता था। समय बढ़ने के बाद सदस्य संख्या लगभग वही रही, पर शाम के समय पुस्तकें लेने वालों की संख्या बढ़ गई।\n\nगद्यांश से सबसे उचित निष्कर्ष क्या है?\n\nThe comparison uses the same reporting definitions in both periods and refers only to ordinary operating days. Base the answer only on the relationships described in the account, not on outside facts.', options: ['दिन में कोई भी पुस्तकालय नहीं आता था।', 'समय बढ़ाने से सदस्य संख्या हमेशा दोगुनी होती है।', 'मजदूरों को पुस्तकों में रुचि नहीं थी।', 'सुविधाजनक समय उपलब्ध होने से उपयोग बढ़ सकता है, भले सदस्य संख्या न बदले।'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'उत्तर गद्यांश में दिए गए मुख्य कारण और परिणाम के संबंध से निकलता है।', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q005', section: 'General Studies II (CSAT)', topic: 'Quantitative reasoning', difficulty: 'hard', question: 'In a field-office exercise, A canteen sells 160 meal coupons at ₹50 each. Price rises by 10% while quantity sold falls by 10%. By what percentage does revenue change? The district officer must decide only from these stated facts.', options: ['0', '-1', '1', '-10'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'New revenue factor = 1.10×0.90 = 0.99, so revenue falls by 1%, i.e. change = -1%.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q006', section: 'General Studies II (CSAT)', topic: 'Pipes and cisterns', difficulty: 'medium', question: 'A citizen-service unit is working through this case. An inlet fills a storage tank in 14 hours while a drain empties a full tank in 28 hours. If both are open together from empty, how long will filling take? Use the stated quantities exactly; no outside assumption is needed.', options: ['28', '9.33', '42', '0'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Net filling rate = 1/14−1/28; its reciprocal is 28 hours.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q007', section: 'General Studies II (CSAT)', topic: 'Hindi comprehension', difficulty: 'medium', question: 'During a district training drill, एक कार्यालय ने आवेदन की स्थिति देखने के लिए ऑनलाइन सुविधा शुरू की। इससे फोन पर स्थिति पूछने वाली कॉल कम हुईं, लेकिन जटिल मामलों पर सलाह की कॉल लगभग उतनी ही रहीं।\n\nइससे क्या पता चलता है?\n\nThe before-and-after observations cover comparable working days and use the same outcome definition. Read the account as a closed evidence set and choose the option that requires the fewest unstated assumptions.', options: ['स्थिति-सूचना का कॉलों से कोई संबंध नहीं है।', 'जटिल मामलों की संख्या शून्य हो गई।', 'ऑनलाइन सुविधा से सभी प्रकार की कॉल समाप्त हो जाती हैं।', 'सरल स्थिति-सूचना ऑनलाइन मिलने से नियमित पूछताछ कम हो सकती है।'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'उत्तर गद्यांश में दिए गए मुख्य कारण और परिणाम के संबंध से निकलता है।', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q008', section: 'General Studies II (CSAT)', topic: 'हिंदी व्याकरण', difficulty: 'easy', question: 'A local programme officer encounters this situation. शुद्ध वाक्य चुनिए। The district officer must decide only from these stated facts.', options: ['प्रत्येक विद्यार्थियों उपस्थित है।', 'प्रत्येक विद्यार्थी उपस्थित हैं।', 'प्रत्येक विद्यार्थी उपस्थित है।', 'प्रत्येक विद्यार्थी उपस्थित हो।'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: '“प्रत्येक विद्यार्थी” एकवचन भाव देता है, इसलिए “है” उचित है।', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q009', section: 'General Studies II (CSAT)', topic: 'Sets and Venn diagrams', difficulty: 'medium', question: 'For a public-service monitoring task, In a survey, 50 people use service A, 42 use service B, 20 use both, and 12 use neither. How many people are in the full survey? Use the stated quantities exactly; no outside assumption is needed.', options: ['92', '84', '72', '8'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Union = 50+42−20=72; exactly one = 50+42−2×20=52; total including neither = 84.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q010', section: 'General Studies II (CSAT)', topic: 'Communication skills', difficulty: 'medium', question: 'A district operations note gives these facts. An email asks for three actions by different dates. Which format communicates the requirements most clearly? Treat every condition in the case as binding.', options: ['List each action with its responsible person and deadline.', 'Put all three actions in one long paragraph without dates.', 'Use only a subject line and no message body.', 'Mention the deadlines but not the actions.'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Explicit action-owner-deadline pairs reduce ambiguity and make follow-up easier.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q011', section: 'General Studies II (CSAT)', topic: 'Spatial reasoning', difficulty: 'medium', question: 'A square sheet is folded once vertically and once horizontally. A single hole is punched away from the fold lines through all layers. How many holes appear when the sheet is fully unfolded?', options: ['8', '4', '1', '2'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Each fold doubles the number of symmetric hole positions. Two folds therefore produce 2² = 4 holes.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q012', section: 'General Studies II (CSAT)', topic: 'English vocabulary', difficulty: 'medium', question: 'While reviewing a district service register, Choose the word opposite in meaning to “scarce”. Use the stated quantities exactly; no outside assumption is needed.', options: ['rare', 'insufficient', 'abundant', 'limited'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: '“Scarce” means in short supply; “abundant” is its opposite.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q013', section: 'General Studies II (CSAT)', topic: 'Percentages', difficulty: 'medium', question: 'In a block-level planning exercise, A district archive increases its weekly output of 250 units by 15% and then reduces the revised target by 20%. What is the final target? Treat every condition in the case as binding.', options: ['200', '287.5', '230', '237.5'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Apply the changes successively: 250 × 1.15 × 0.8 = 230.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q014', section: 'General Studies II (CSAT)', topic: 'हिंदी व्याकरण', difficulty: 'medium', question: 'निम्नलिखित में कौन-सा वाक्य कर्तृवाच्य में है?', options: ['समिति से प्रस्ताव स्वीकार हुआ।', 'प्रस्ताव स्वीकार किया गया।', 'प्रस्ताव समिति द्वारा स्वीकार किया गया।', 'समिति ने प्रस्ताव स्वीकार किया।'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: '“समिति ने प्रस्ताव स्वीकार किया।” में “समिति” कर्ता है और क्रिया सक्रिय रूप में है।', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q015', section: 'General Studies II (CSAT)', topic: 'Ordering', difficulty: 'medium', question: 'A district coordination team records the following situation. Four files P, Q, R and S must be reviewed one at a time. P is before Q, R is after Q, and S is before P. Which order is possible? Use the stated quantities exactly; no outside assumption is needed.', options: ['R, S, P, Q', 'S, P, Q, R', 'P, S, Q, R', 'S, Q, P, R'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Only S, P, Q, R satisfies S before P before Q before R.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q016', section: 'General Studies II (CSAT)', topic: 'English vocabulary', difficulty: 'easy', question: 'For a local-service decision note, Choose the word closest in meaning to “concise”. Treat every condition in the case as binding.', options: ['brief', 'uncertain', 'decorative', 'delayed'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: '“Concise” means expressing much in few words; “brief” is the closest option.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q017', section: 'General Studies II (CSAT)', topic: 'Decision making', difficulty: 'hard', question: 'A procurement rule requires three quotations unless a documented emergency exception is approved. Only two quotations are available and there is no emergency approval. What should the officer do?', options: ['Seek the required third quotation or obtain a valid approved exception before proceeding.', 'Invent a third quotation for the file.', 'Ignore the rule if the purchase is small.', 'Proceed because two quotations are almost three.'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The stated condition has not been met, so the lawful choices are to satisfy it or secure a valid exception.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q018', section: 'General Studies II (CSAT)', topic: 'Data interpretation', difficulty: 'easy', question: 'Six complaint-resolution times are 11, 14, 18, 20, 27 and 32 minutes. What is the median resolution time?', options: ['18', '20', '19', '20.33'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'With six ordered observations, the median is the average of the third and fourth values: (18+20)/2 = 19 minutes.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q019', section: 'General Studies II (CSAT)', topic: 'Sequence of events', difficulty: 'medium', question: 'During a district training drill, A complaint must be registered before it is assigned, and assigned before it is closed. Which event order is valid? Treat every condition in the case as binding.', options: ['Register → Close → Assign', 'Close → Register → Assign', 'Register → Assign → Close', 'Assign → Register → Close'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The stated prerequisites require registration first, assignment second and closure last.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q020', section: 'General Studies II (CSAT)', topic: 'Number system', difficulty: 'easy', question: 'A local programme officer encounters this situation. For the integers 48 and 84, what is their greatest common divisor? The district officer must decide only from these stated facts.', options: ['84', '12', '36', '348'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'gcd(48,84)=12; therefore lcm=4032/12=336. The requested value is 12.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q021', section: 'General Studies II (CSAT)', topic: 'Hindi comprehension', difficulty: 'medium', question: 'For a public-service monitoring task, एक स्कूल ने पौधारोपण के साथ हर पौधे की छह महीने तक देखभाल की जिम्मेदारी भी तय की। कम पौधे लगाए गए, पर जीवित रहने का प्रतिशत पहले से अधिक रहा।\n\nयह उदाहरण किस बात पर जोर देता है?\n\nThe district note keeps the reporting window and measurement rule unchanged, so the stated difference is directly comparable. Treat the stated observations as the complete evidence for this question and select the strongest supported inference.', options: ['जीवित रहने का प्रतिशत मापना व्यर्थ है।', 'देखभाल से पौधों पर कोई प्रभाव नहीं पड़ता।', 'अधिक पौधे लगाना हमेशा बेहतर होता है।', 'केवल गतिविधि की संख्या नहीं, परिणाम की गुणवत्ता भी महत्त्वपूर्ण है।'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'उत्तर गद्यांश में दिए गए मुख्य कारण और परिणाम के संबंध से निकलता है।', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q022', section: 'General Studies II (CSAT)', topic: 'Communication skills', difficulty: 'hard', question: 'A district operations note gives these facts. A manager must announce a change that affects different teams in different ways. Which communication method is most suitable? Treat every condition in the case as binding.', options: ['Send only the most affected team the information.', 'Give the common rule once, then specify team-specific effects and provide a channel for questions.', 'Use a vague one-line message to avoid questions.', 'Rely on rumours to spread the details.'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'A layered message gives everyone the shared rule while addressing differing impacts and allowing clarification.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q023', section: 'General Studies II (CSAT)', topic: 'Ages', difficulty: 'medium', question: 'In a local administrative case study, Rina is 34 years old and her colleague is 12 years older. What will be the ratio of the colleague’s age to Rina’s age after 7 years? The district officer must decide only from these stated facts.', options: ['41:53', '19:41', '46:34', '53:41'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'After 7 years their ages are 53 and 41, so the ratio is 53:41.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q024', section: 'General Studies II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'A seed cooperative tested a new millet variety on the same trial plots in a dry season, a normal season and an unusually wet season. The variety ranked first in the wet year but only second in each of the other two years. The committee therefore used all three seasons before deciding whether to recommend it.\n\nWhy was the multi-season comparison useful?', options: ['It made field observations unnecessary.', 'It guaranteed identical rainfall every year.', 'It reduced the risk of drawing a conclusion from an atypical single season.', 'It proved that wet years never matter.'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Using three seasons reduces the chance that an unusual wet year alone determines the recommendation.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q025', section: 'General Studies II (CSAT)', topic: 'Problem solving', difficulty: 'hard', question: 'In a block-level planning exercise, A data-entry error appears in 4% of sampled records. Before redesigning the entire system, what is the most informative next step? Treat every condition in the case as binding.', options: ['Assume every error has the same cause.', 'Classify the errors by type and process stage to identify their main source.', 'Double every target regardless of the cause.', 'Delete the sample results.'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Error classification can reveal whether a specific step or error type accounts for most of the problem.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q026', section: 'General Studies II (CSAT)', topic: 'हिंदी शब्दज्ञान', difficulty: 'easy', question: '“न्यून” का विलोम चुनिए।', options: ['कम', 'अधिक', 'लघु', 'सूक्ष्म'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: '“न्यून” का अर्थ कम होता है; इसका विलोम “अधिक” है।', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q027', section: 'General Studies II (CSAT)', topic: 'Data interpretation', difficulty: 'medium', question: 'A district coordination team records the following situation. A dashboard shows 150 resolved cases in one quarter and 200 in the next. What is the percentage increase? Use the stated quantities exactly; no outside assumption is needed.', options: ['33.33', '50', '25', '43.33'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Increase = 50; divide by the original 150: (50/150)×100 = 33.33%.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q028', section: 'General Studies II (CSAT)', topic: 'Problem solving', difficulty: 'medium', question: 'For a local-service decision note, A queue is growing because one verification step takes much longer than all others. What is the most useful first diagnostic? Treat every condition in the case as binding.', options: ['Add staff randomly to every step.', 'Stop recording processing times.', 'Measure where time is spent at each step to confirm the bottleneck.', 'Remove the verification requirement without authority.'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Process-time measurement identifies whether the suspected step is truly constraining throughput.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q029', section: 'General Studies II (CSAT)', topic: 'Arithmetic', difficulty: 'medium', question: 'In a field-office exercise, A service has a base charge of ₹180, a 5% surcharge on the base charge, and a fixed processing fee of ₹50. What is the total payable? The district officer must decide only from these stated facts.', options: ['241.5', '189', '239', '230'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Surcharge = ₹9. Total = 180+9+50 = ₹239.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q030', section: 'General Studies II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'A citizen-service unit is working through this case. A clinic noticed that many patients arrived early but still waited because registration opened later than the waiting room. It shifted one registrar’s start time forward by thirty minutes. Average waiting time fell without adding staff.\n\nWhat caused the improvement?\n\nNo change in staffing or reporting definitions is recorded during the period described in the account. Use only the facts supplied in the passage and distinguish observation from speculation.', options: ['Staff timing was better aligned with when demand began.', 'Registration was removed.', 'Patients were asked to arrive later by several hours.', 'The clinic increased the number of patients.'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The answer follows from the central relationship stated in the passage.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q031', section: 'General Studies II (CSAT)', topic: 'Profit, loss and discount', difficulty: 'medium', question: 'A tool has a marked price of ₹600. It is sold after successive discounts of 10% and 5%. If its cost price is ₹450, what is the profit percentage on cost?', options: ['12', '14', '18', '20'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Selling price = 600×0.90×0.95 = ₹513. Profit = 513−450 = ₹63, so profit percentage = 63/450×100 = 14%.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q032', section: 'General Studies II (CSAT)', topic: 'Logical reasoning', difficulty: 'medium', question: 'A local programme officer encounters this situation. All field maps are records. Some records are digitised. Which conclusion must be true? The district officer must decide only from these stated facts.', options: ['All records are field maps.', 'All field maps are records.', 'No digitised item is a field map.', 'Some field maps are digitised.'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The first statement directly guarantees that every field map belongs to the set of records; the other claims do not necessarily follow.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q033', section: 'General Studies II (CSAT)', topic: 'Interpersonal skills', difficulty: 'medium', question: 'For a public-service monitoring task, A junior employee raises a concern that contradicts the team leader’s initial view. What response best supports sound teamwork? Use the stated quantities exactly; no outside assumption is needed.', options: ['Treat disagreement as misconduct.', 'Dismiss it because of the employee’s rank.', 'Change the subject immediately.', 'Ask for the evidence and evaluate the concern on its merits.'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Evaluating evidence rather than hierarchy supports psychological safety and better decisions.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q034', section: 'General Studies II (CSAT)', topic: 'Cause and effect', difficulty: 'medium', question: 'A district operations note gives these facts. After a server upgrade, average page-loading time fell from 4 seconds to 1.5 seconds while traffic volume stayed nearly unchanged. Which inference is best supported? Treat every condition in the case as binding.', options: ['The upgrade likely improved system performance.', 'Traffic volume caused the upgrade.', 'Page-loading time is unrelated to server performance.', 'The website received fewer requests.'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'With traffic approximately unchanged, the sharp reduction in loading time is consistent with the upgrade improving performance.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q035', section: 'General Studies II (CSAT)', topic: 'Relative speed', difficulty: 'medium', question: 'Bus A leaves town P toward town Q at 48 km/h. Towns P and Q are 240 km apart. One hour later, Bus B leaves Q toward P at 72 km/h. How many minutes after Bus B starts do the buses meet?', options: ['96', '120', '144', '160'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'In Bus A’s one-hour head start it covers 48 km, leaving 192 km. Once Bus B starts, closing speed is 48+72=120 km/h, so time is 192/120=1.6 hours = 96 minutes.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q036', section: 'General Studies II (CSAT)', topic: 'Clock reasoning', difficulty: 'medium', question: 'While reviewing a district service register, What is the smaller angle between the hour and minute hands at 5:30? Use the stated quantities exactly; no outside assumption is needed.', options: ['30', '16', '345', '15'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Hour-hand angle = 30×5+0.5×30; minute-hand angle = 6×30. Their smaller difference is 15°.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q037', section: 'General Studies II (CSAT)', topic: 'Boats and streams', difficulty: 'easy', question: 'In a block-level planning exercise, A survey boat moves downstream at 14 km/h and upstream at 12 km/h. What is the stream speed? Treat every condition in the case as binding.', options: ['1', '12', '2', '13'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Still-water speed = (14+12)/2 = 13 and stream speed = (14−12)/2 = 1 km/h.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q038', section: 'General Studies II (CSAT)', topic: 'Counting', difficulty: 'medium', question: 'During a public-facility review, A committee must choose 2 representatives from 5 eligible volunteers. How many different groups are possible? The district officer must decide only from these stated facts.', options: ['11', '20', '10', '15'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The order of selection does not matter, so the number is C(5,2) = 10.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q039', section: 'General Studies II (CSAT)', topic: 'Decision making', difficulty: 'medium', question: 'A district coordination team records the following situation. A deadline falls on a declared office holiday, and the written instruction says such deadlines shift to the next working day. What should be communicated? Use the stated quantities exactly; no outside assumption is needed.', options: ['The deadline is cancelled permanently.', 'The deadline stays on the holiday.', 'The revised deadline is the next working day.', 'The deadline moves to the previous working day.'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The written instruction directly specifies the next-working-day rule.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q040', section: 'General Studies II (CSAT)', topic: 'Remainders', difficulty: 'easy', question: 'For a local-service decision note, An inventory count is 182. What remainder is left when it is divided by 9? Treat every condition in the case as binding.', options: ['2', '1', '0', '7'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: '182 = 9×20+2, so the remainder is 2.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q041', section: 'General Studies II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'In a field-office exercise, A district office tested a shorter application form. Completion time fell, but error rates stayed unchanged. The office therefore kept the shorter form and added a separate help note for unusual cases.\n\nWhich statement best describes the office’s decision?\n\nThe district note keeps the reporting window and measurement rule unchanged, so the stated difference is directly comparable. Treat the stated observations as the complete evidence for this question and select the strongest supported inference.', options: ['It assumed unusual cases never occur.', 'It retained the efficiency gain while providing extra guidance for exceptions.', 'It removed all guidance from the process.', 'It rejected the shorter form because errors increased.'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The answer follows from the central relationship stated in the passage.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q042', section: 'General Studies II (CSAT)', topic: 'Work and time', difficulty: 'medium', question: 'A citizen-service unit is working through this case. Two audit teams can independently finish a review in 10 days and 15 days. Working together at constant rates, how many days do they take? Use the stated quantities exactly; no outside assumption is needed.', options: ['12.5', '5', '6', '7'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Combined rate = 1/10+1/15; time is its reciprocal = 6 days.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q043', section: 'General Studies II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'During a district training drill, A forest nursery measured survival rates rather than only the number of saplings planted. One site planted the most saplings but had poor survival because watering was irregular.\n\nWhat does the passage suggest about performance measures?\n\nThe before-and-after observations cover comparable working days and use the same outcome definition. Read the account as a closed evidence set and choose the option that requires the fewest unstated assumptions.', options: ['Planting more saplings always guarantees success.', 'Outcome measures can reveal weaknesses that activity counts alone hide.', 'Survival rates are unrelated to watering.', 'Only activity counts should be reported.'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The answer follows from the central relationship stated in the passage.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q044', section: 'General Studies II (CSAT)', topic: 'Compound interest', difficulty: 'medium', question: 'A local programme officer encounters this situation. A reserve of ₹11000 grows at 15% per year compounded annually for two years. What is the compound interest? The district officer must decide only from these stated facts.', options: ['3547.5', '14547.5', '3300', '3795'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Amount = 11000(1+15/100)^2 = ₹14547.5; interest = ₹3547.5.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q045', section: 'General Studies II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'For a public-service monitoring task, A town library extended weekend hours after observing that many working adults could not visit on weekdays. Membership did not change much, but weekend borrowing rose sharply. The library concluded that access time, not lack of interest, had been the main barrier for this group.\n\nWhich inference is most strongly warranted by the passage?\n\nThe district note keeps the reporting window and measurement rule unchanged, so the stated difference is directly comparable. Treat the stated observations as the complete evidence for this question and select the strongest supported inference.', options: ['Working adults are generally uninterested in libraries.', 'Convenient opening hours can affect use even when underlying interest is unchanged.', 'Weekday borrowing must have stopped completely.', 'Membership always rises when hours are extended.'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The answer follows from the central relationship stated in the passage.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q046', section: 'General Studies II (CSAT)', topic: 'English grammar', difficulty: 'easy', question: 'A district operations note gives these facts. Choose the grammatically correct sentence. Treat every condition in the case as binding.', options: ['Each files is numbered.', 'Each of the files are numbered.', 'Each of the file are numbered.', 'Each of the files is numbered.'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: '“Each” takes a singular verb: “is.”', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q047', section: 'General Studies II (CSAT)', topic: 'Statement and assumption', difficulty: 'hard', question: 'In a local administrative case study, Statement: “To reduce missed appointments, the office will send a reminder one day before each booking.” Which assumption is most necessary? The district officer must decide only from these stated facts.', options: ['Every missed appointment is deliberate.', 'Reminders always eliminate all absences.', 'At least some missed appointments occur because people forget their bookings.', 'Appointments should be abolished.'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The intervention makes sense only if forgetting contributes to at least some missed appointments; it need not solve every absence.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q048', section: 'General Studies II (CSAT)', topic: 'Interpersonal skills', difficulty: 'medium', question: 'While reviewing a district service register, Two colleagues disagree about who should prepare a report. Which approach is most likely to resolve the conflict constructively? Use the stated quantities exactly; no outside assumption is needed.', options: ['Clarify responsibilities and workload, then agree on a division tied to the deadline.', 'Send contradictory versions to the supervisor.', 'Focus on who is personally at fault.', 'Delay the report until the disagreement disappears.'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Separating the task requirements from personal blame helps the team reach a workable allocation.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q049', section: 'General Studies II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'In a block-level planning exercise, An office replaced one long annual training session with six brief sessions spread across the year. Staff reported that they could apply each topic before the next session and remember procedures better.\n\nWhat advantage of spaced training is highlighted?\n\nThe district note keeps the reporting window and measurement rule unchanged, so the stated difference is directly comparable. Treat the stated observations as the complete evidence for this question and select the strongest supported inference.', options: ['It eliminates the need to apply procedures.', 'It guarantees every learner identical performance.', 'It makes the total training time irrelevant.', 'Learners can practise material between sessions, supporting retention.'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The answer follows from the central relationship stated in the passage.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q050', section: 'General Studies II (CSAT)', topic: 'Syllogism', difficulty: 'hard', question: 'During a public-facility review, No temporary passes are permanent cards. Some visitor IDs are temporary passes. Which conclusion follows necessarily? The district officer must decide only from these stated facts.', options: ['Some permanent cards are temporary passes.', 'Some visitor IDs are not permanent cards.', 'No visitor ID is a permanent card.', 'All visitor IDs are permanent cards.'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The visitor IDs that are temporary passes cannot be permanent cards, so at least some visitor IDs are not permanent cards.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q051', section: 'General Studies II (CSAT)', topic: 'Direction sense', difficulty: 'medium', question: 'A district coordination team records the following situation. A surveyor walks 6 km north, 8 km east, and then 6 km south. Where is the surveyor relative to the starting point? Use the stated quantities exactly; no outside assumption is needed.', options: ['6 km north', '8 km east', '8 km west', '10 km north-east'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The north and south movements cancel, leaving a net displacement of 8 km east.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q052', section: 'General Studies II (CSAT)', topic: 'Probability', difficulty: 'easy', question: 'For a local-service decision note, A box in a market inspection unit contains 7 red, 4 blue and 3 green tags. One tag is selected at random. What is the probability of selecting a red tag? Treat every condition in the case as binding.', options: ['7/11', '1/14', '7/14', '4/14'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'There are 14 tags, of which 7 are red, so the probability is 7/14.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q053', section: 'General Studies II (CSAT)', topic: 'Family relations', difficulty: 'medium', question: 'In a field-office exercise, Maya says, “The man in the photograph is the son of my mother’s only brother.” How is the man related to Maya? The district officer must decide only from these stated facts.', options: ['Nephew', 'Brother', 'Uncle', 'Cousin'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Maya’s mother’s brother is her maternal uncle; his son is Maya’s cousin.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q054', section: 'General Studies II (CSAT)', topic: 'Letter pattern', difficulty: 'medium', question: 'A citizen-service unit is working through this case. In the pattern AZ, BY, CX, DW, what pair comes next? Use the stated quantities exactly; no outside assumption is needed.', options: ['EU', 'FV', 'EW', 'EV'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The first letter moves forward A,B,C,D,E while the second moves backward Z,Y,X,W,V.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q055', section: 'General Studies II (CSAT)', topic: 'Hindi comprehension', difficulty: 'medium', question: 'एक नगर हेल्पलाइन ने पानी की शिकायतों को इलाके और समस्या के प्रकार के अनुसार दर्ज करना शुरू किया। दो सप्ताह के आँकड़ों से पता चला कि एक ही क्षेत्र में कम दबाव की शिकायतें बार-बार आ रही थीं। जाँच में वहाँ का खराब वाल्व मिला।\n\nशिकायतों का वर्गीकरण क्यों उपयोगी रहा?', options: ['सभी शिकायतें एक जैसी मान ली गईं।', 'उससे प्रमुख समस्या का स्रोत पहचानना आसान हुआ।', 'उससे यात्रियों की संख्या घट गई।', 'टिकट खिड़की बंद कर दी गई।'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'इलाके और समस्या के प्रकार के अनुसार वर्गीकरण करने से बार-बार आने वाली शिकायतों का पैटर्न दिखा और मुख्य स्रोत तक पहुँचना आसान हुआ।', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q056', section: 'General Studies II (CSAT)', topic: 'Number series', difficulty: 'medium', question: 'Find the next term in the series 2, 6, 15, 31, 56, …', options: ['86', '92', '81', '96'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Successive additions are 4, 9, 16 and 25, i.e. 2², 3², 4² and 5². Add 6² = 36 to 56 to get 92.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q057', section: 'General Studies II (CSAT)', topic: 'Ratio and proportion', difficulty: 'easy', question: 'For a public-service monitoring task, Two counters process 85 and 55 requests. What percentage of the combined requests were handled by the first counter? Use the stated quantities exactly; no outside assumption is needed.', options: ['60.71', '154.55', '39.29', '30'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Combined requests = 140; first-counter share = 85/140×100 = 60.71%.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q058', section: 'General Studies II (CSAT)', topic: 'Ranking', difficulty: 'easy', question: 'A district operations note gives these facts. In a merit list, Biren is above Charu, and Charu is above Deepak. Which conclusion necessarily follows? Treat every condition in the case as binding.', options: ['Biren is above Deepak.', 'Charu is below Deepak.', 'Biren and Deepak are tied.', 'Deepak is above Biren.'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The order is Biren > Charu > Deepak; therefore Biren is above Deepak.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q059', section: 'General Studies II (CSAT)', topic: 'Work rate', difficulty: 'medium', question: 'In a local administrative case study, A scanning machine processes 16 folders per hour for 5 hours, then 20 per hour for 3 hours. How many folders are processed in all? The district officer must decide only from these stated facts.', options: ['148', '124', '140', '36'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'First phase gives 80; second gives 60; total = 140.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q060', section: 'General Studies II (CSAT)', topic: 'Hindi comprehension', difficulty: 'medium', question: 'While reviewing a district service register, एक जल समिति ने केवल नए नल लगाने के बजाय पुराने रिसावों की सूची बनाई और पहले बड़े रिसाव ठीक किए। अगले महीने पानी की कुल आपूर्ति वही रही, लेकिन घरों तक पहुँचने वाला पानी बढ़ गया।\n\nसुधार का मुख्य कारण क्या था?\n\nThe comparison uses the same reporting definitions in both periods and refers only to ordinary operating days. Base the answer only on the relationships described in the account, not on outside facts.', options: ['कुल जल आपूर्ति अचानक बढ़ गई।', 'वितरण में होने वाली हानि कम हुई।', 'नलों की संख्या घट गई।', 'सभी घरों ने पानी लेना बंद कर दिया।'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'उत्तर गद्यांश में दिए गए मुख्य कारण और परिणाम के संबंध से निकलता है।', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q061', section: 'General Studies II (CSAT)', topic: 'English grammar', difficulty: 'medium', question: 'In a block-level planning exercise, Choose the sentence with correct subject–verb agreement. Treat every condition in the case as binding.', options: ['Neither the manager nor the assistants are available.', 'Neither the manager or the assistants are available.', 'Neither the manager nor the assistants is available.', 'Neither manager nor assistants is available.'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'With “neither…nor,” the verb agrees with the nearer subject “assistants,” so “are” is correct.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q062', section: 'General Studies II (CSAT)', topic: 'Mixtures', difficulty: 'hard', question: 'During a public-facility review, A tank contains 60 L of a solution that is 30% concentrate. 15 L of the mixture is withdrawn and replaced by water. What is the new percentage of concentrate? The district officer must decide only from these stated facts.', options: ['27.5', '5', '22.5', '23.5'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Withdrawal removes concentrate proportionally. Remaining concentrate = 13.5 L in 60 L, giving 22.5%.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q063', section: 'General Studies II (CSAT)', topic: 'Selection constraints', difficulty: 'hard', question: 'A district coordination team records the following situation. A three-person panel is chosen from K, L, M, N and P. K and L cannot serve together. M must serve if P serves. Which panel is valid? Use the stated quantities exactly; no outside assumption is needed.', options: ['K, L, M', 'L, N, P', 'K, L, P', 'K, M, P'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'K,M,P respects K/L separation and includes M whenever P is present. The other options violate at least one rule.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q064', section: 'General Studies II (CSAT)', topic: 'Communication skills', difficulty: 'easy', question: 'For a local-service decision note, Which question is most useful for clarifying an ambiguous request? Treat every condition in the case as binding.', options: ['“Which outcome do you need, and by what time?”', '“Is everything urgent?”', '“Can I ignore this?”', '“Why did you send this?”'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'It asks for the two missing operational details: the required result and the deadline.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q065', section: 'General Studies II (CSAT)', topic: 'Communication skills', difficulty: 'medium', question: 'In a field-office exercise, A notice contains a technical term unfamiliar to most residents. Which revision would improve clarity the most? The district officer must decide only from these stated facts.', options: ['Remove the deadline from the notice.', 'Add more technical terms for precision.', 'Make the sentence longer without defining the term.', 'Replace the term with plain language or define it at first use.'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Plain language or a brief definition makes the message understandable without changing its substance.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q066', section: 'General Studies II (CSAT)', topic: 'Averages', difficulty: 'easy', question: 'A citizen-service unit is working through this case. Three inspection rounds take 12, 18 and 30 minutes. What is the arithmetic mean time? Use the stated quantities exactly; no outside assumption is needed.', options: ['20', '23', '18', '15'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Mean = (12+18+30)/3 = 20 minutes.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q067', section: 'General Studies II (CSAT)', topic: 'Trains', difficulty: 'medium', question: 'During a district training drill, A train 120 m long passes a platform 220 m long at 63 km/h. How many seconds does it take to clear the platform completely? Treat every condition in the case as binding.', options: ['19.43', '24.43', '6.86', '12.57'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Distance to clear = 340 m; speed = 17.5 m/s; time = 19.43 s.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q068', section: 'General Studies II (CSAT)', topic: 'Average speed', difficulty: 'hard', question: 'A local programme officer encounters this situation. A patrol covers two equal-distance legs at 50 km/h and 55 km/h. What is the average speed over the two legs? The district officer must decide only from these stated facts.', options: ['57.38', '52.44', '52.5', '52.38'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'For equal distances, average speed is the harmonic mean 2ab/(a+b) = 52.38 km/h.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q069', section: 'General Studies II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'A land-records office digitised fragile survey maps. Before any original map was released for archival disposal, a second staff member checked both the image and its file checksum. One batch failed the check and was rescanned from the still-available originals.\n\nWhich risk-control principle is illustrated?', options: ['Blurred pages cannot be rescanned.', 'Verify the replacement before discarding the original.', 'Destroy originals before checking scans.', 'Quality checks are unnecessary when scanning is fast.'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The office verified that the digital replacement was usable before giving up the original source, which preserved a recovery path when a scan failed.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q070', section: 'General Studies II (CSAT)', topic: 'Decision making', difficulty: 'hard', question: 'A public counter has one urgent medical-document request and several routine requests that arrived earlier. The written rule permits priority for documented emergencies. What should the officer do?', options: ['Prioritise the requester without checking any evidence.', 'Close the counter until the queue becomes shorter.', 'Verify the emergency evidence and, if valid, apply the permitted priority rule.', 'Always serve strictly by arrival time even when the rule allows emergency priority.'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The stated policy creates a lawful exception, but it should be applied only after the emergency condition is verified.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q071', section: 'General Studies II (CSAT)', topic: 'Coding-decoding', difficulty: 'medium', question: 'In a local administrative case study, A code replaces each letter by the next letter of the alphabet. Under this rule, FILE becomes GJMF. How is MAP coded? The district officer must decide only from these stated facts.', options: ['LZO', 'NBQ', 'NBO', 'MBQ'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'M→N, A→B and P→Q, so MAP becomes NBQ.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q072', section: 'General Studies II (CSAT)', topic: 'Decision making', difficulty: 'medium', question: 'A form is incomplete, but the missing field can be supplied immediately by the applicant. The rules allow correction before submission closes. Which action is most appropriate?', options: ['Reject it immediately despite the correction rule.', 'Point out the missing field and allow the applicant to complete it within the permitted process.', 'Fill the field with a guess.', 'Accept it as complete without correction.'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The rule expressly allows timely correction, so the applicant should be given that lawful opportunity.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q073', section: 'General Studies II (CSAT)', topic: 'Percentages', difficulty: 'easy', question: 'In a block-level planning exercise, Of 1100 registered households, 40% chose digital notices. How many chose another mode? Treat every condition in the case as binding.', options: ['660', '1060', '710', '440'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The non-digital share is 60% of 1100 = 660 households.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q074', section: 'General Studies II (CSAT)', topic: 'Speed, distance and time', difficulty: 'medium', question: 'During a public-facility review, A field vehicle covers 180 km at 55 km/h and stops for 40 minutes en route. What is its average speed for the entire journey? The district officer must decide only from these stated facts.', options: ['50.69', '45.69', '55', '69.07'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Total elapsed time = 180/55+40/60 = 3.94 h; average speed = 180/3.94 = 45.69 km/h.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q075', section: 'General Studies II (CSAT)', topic: 'Percentages', difficulty: 'medium', question: 'A district coordination team records the following situation. After a 18% reduction, the monthly paper use of a river-basin office is 560 reams. What was the use before the reduction? Use the stated quantities exactly; no outside assumption is needed.', options: ['474.58', '459.2', '682.93', '660.8'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'If the original amount is x, then x(1−18/100)=560; hence x=682.93.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q076', section: 'General Studies II (CSAT)', topic: 'Analogy', difficulty: 'easy', question: 'Map is to navigation as thermometer is to:', options: ['measuring distance', 'measuring temperature', 'weighing mass', 'recording rainfall'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'A map is used for navigation; a thermometer is used for measuring temperature.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q077', section: 'General Studies II (CSAT)', topic: 'Truth and lies', difficulty: 'hard', question: 'In a field-office exercise, Exactly one of Arun and Bela is telling the truth. Arun says, “Bela is lying.” Bela says, “We are both telling the truth.” Who is telling the truth? The district officer must decide only from these stated facts.', options: ['Arun only', 'Bela only', 'Both Arun and Bela', 'Neither Arun nor Bela'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'If Bela were truthful, both would be truthful, contradicting the condition. Therefore Bela lies and Arun’s statement is true.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q078', section: 'General Studies II (CSAT)', topic: 'Logical consistency', difficulty: 'hard', question: 'A citizen-service unit is working through this case. If every approved project has a budget code, and Project Z has no budget code, what can be concluded? Use the stated quantities exactly; no outside assumption is needed.', options: ['Project Z must be approved.', 'No approved project has a budget code.', 'Project Z is not approved.', 'Project Z has two budget codes.'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The contrapositive of “approved → budget code” is “no budget code → not approved.”', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q079', section: 'General Studies II (CSAT)', topic: 'Hindi comprehension', difficulty: 'medium', question: 'एक स्वास्थ्य दल ने दूर-दराज़ गाँवों तक पहुँचने के लिए दो अतिरिक्त वाहन जोड़े, फिर भी कई निर्धारित दौरे छूटते रहे। बाद में पता चला कि मार्ग-सूची में कुछ गाँव दो बार और कुछ गाँव बिल्कुल नहीं थे। सूची सुधारने के बाद, उन्हीं वाहनों से अधिक दौरे समय पर पूरे हुए।\n\nगद्यांश का मुख्य संदेश क्या है?', options: ['सिर्फ संसाधन बढ़ाना पर्याप्त नहीं; प्रक्रिया की व्यवस्था भी महत्त्वपूर्ण है।', 'अधिक गाड़ियाँ हमेशा समस्या हल करती हैं।', 'कचरा संग्रह बंद कर देना चाहिए।', 'मार्ग-योजना का प्रदर्शन से कोई संबंध नहीं है।'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'वाहन बढ़ाने से अकेले समस्या नहीं सुलझी; मार्ग-सूची की प्रक्रिया सुधारने पर परिणाम बेहतर हुआ। इसलिए संसाधन के साथ प्रक्रिया की व्यवस्था भी महत्त्वपूर्ण है।', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q080', section: 'General Studies II (CSAT)', topic: 'Problem solving', difficulty: 'hard', question: 'A water-tanker route is delayed because two roads are closed. The goal is to reach all scheduled villages today without exceeding the driver\'s legal hours. Which first step is most defensible?', options: ['Recalculate feasible routes and travel times under the closures before committing to a new sequence.', 'Skip villages at random.', 'Continue on the original route despite the closures.', 'Ask the driver to exceed the legal hours.'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'A feasible plan must first reflect the new constraints; only then can stops be resequenced lawfully.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q081', section: 'General Studies II (CSAT)', topic: 'हिंदी शब्दज्ञान', difficulty: 'medium', question: 'For a public-service monitoring task, “सुगम” का सबसे निकट अर्थ क्या है? Use the stated quantities exactly; no outside assumption is needed.', options: ['दुर्लभ', 'अस्पष्ट', 'आसान', 'कठोर'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: '“सुगम” का अर्थ है जिसे आसानी से किया या समझा जा सके।', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q082', section: 'General Studies II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'A district operations note gives these facts. A municipal team published both the number of potholes repaired and the number reported. Residents could then see that repairs had risen, but reports had risen even faster.\n\nWhy is reporting both figures more informative?\n\nNo change in staffing or reporting definitions is recorded during the period described in the account. Use only the facts supplied in the passage and distinguish observation from speculation.', options: ['It ensures every pothole is repaired immediately.', 'It makes the number of reports irrelevant.', 'It proves that more repairs always mean fewer reports.', 'It shows output relative to the scale of demand rather than output alone.'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The answer follows from the central relationship stated in the passage.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q083', section: 'General Studies II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'A college canteen already had separate wet- and dry-waste bins, but many items were placed in the wrong bin. It then posted large picture examples of food scraps, paper cups and wrappers above the openings. Mis-sorting declined the following week.\n\nWhat most likely changed after the visual examples were added?', options: ['Collection crews removed all bins.', 'The market stopped producing waste.', 'Wet and dry waste became chemically identical.', 'Users became better able to sort waste correctly.'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The labels provided concrete sorting cues, so the fall in mis-sorting is consistent with users becoming better able to sort waste correctly.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q084', section: 'General Studies II (CSAT)', topic: 'Work rate', difficulty: 'hard', question: 'Twelve workers operating 6 hours daily for 6 days process 864 records at a constant per-worker rate. If 14 workers operate 5 hours daily at the same rate, how many days are required for the same workload?', options: ['6.17', '7.2', '5.14', '8'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Work is proportional to workers × hours × days. Required days = 12×6×6/(14×5) = 6.17.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q085', section: 'General Studies II (CSAT)', topic: 'Interpersonal skills', difficulty: 'easy', question: 'In a block-level planning exercise, When a citizen is speaking about a complaint, active listening is best shown by: Treat every condition in the case as binding.', options: ['interrupting with a solution before the explanation ends.', 'looking away while completing unrelated work.', 'changing the subject to a different complaint.', 'summarising the main point and checking that it was understood correctly.'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'A brief summary and confirmation demonstrate attention and reduce misunderstanding.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q086', section: 'General Studies II (CSAT)', topic: 'हिंदी व्याकरण', difficulty: 'medium', question: 'During a public-facility review, रिक्त स्थान भरिए: “अधिकारी ने पत्र ___ हस्ताक्षर किए।” The district officer must decide only from these stated facts.', options: ['से', 'की', 'पर', 'को'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'मानक प्रयोग “पत्र पर हस्ताक्षर करना” है।', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q087', section: 'General Studies II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'A district coordination team records the following situation. A school introduced silent reading for fifteen minutes each morning. Teachers did not require summaries every day; instead, they periodically discussed what students had chosen to read. Over a term, voluntary library visits increased.\n\nWhich explanation is most consistent with the passage?\n\nThe before-and-after observations cover comparable working days and use the same outcome definition. Read the account as a closed evidence set and choose the option that requires the fewest unstated assumptions.', options: ['Daily written summaries caused the increase.', 'Students were forbidden to choose books.', 'Library visits declined over the term.', 'Regular low-pressure reading time may have encouraged greater interest in reading.'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'The answer follows from the central relationship stated in the passage.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q088', section: 'General Studies II (CSAT)', topic: 'Algebra', difficulty: 'easy', question: 'For a local-service decision note, If 4x + 7 = 31, what is x? Treat every condition in the case as binding.', options: ['7.75', '7', '5', '6'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: '4x=24; therefore x=24/4=6.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q089', section: 'General Studies II (CSAT)', topic: 'Digit reasoning', difficulty: 'medium', question: 'In a two-digit number, the units digit is twice the tens digit and the sum of the digits is 9. What is the number?', options: ['63', '27', '36', '39'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Let the tens digit be x; then the units digit is 2x. Since x+2x=9, x=3 and the number is 36.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q090', section: 'General Studies II (CSAT)', topic: 'Ratio and proportion', difficulty: 'easy', question: 'A citizen-service unit is working through this case. A grant of ₹1140 thousand is divided among three units in the ratio 3:5:5. How many thousand rupees does the second unit receive? Use the stated quantities exactly; no outside assumption is needed.', options: ['526.15', '263.08', '394.62', '438.46'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Total ratio parts = 13; the second share is 5/13 of 1140 = 438.46 thousand.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q091', section: 'General Studies II (CSAT)', topic: 'Conditional reasoning', difficulty: 'hard', question: 'During a district training drill, A permit is issued only if both identity verification and fee payment are complete. Identity verification is complete, but the fee is unpaid. What follows? Treat every condition in the case as binding.', options: ['Fee payment is irrelevant once identity is verified.', 'The permit must be issued.', 'The permit cannot yet be issued.', 'Identity verification must be repeated.'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Both conditions are necessary. Since fee payment is incomplete, the permit condition is not satisfied.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q092', section: 'General Studies II (CSAT)', topic: 'Set reasoning', difficulty: 'medium', question: 'A local programme officer encounters this situation. Every red label is urgent. No urgent label is archived. Which conclusion is logically unavoidable? The district officer must decide only from these stated facts.', options: ['Every archived label is red.', 'Some red labels are archived.', 'No urgent label is red.', 'No red label is archived.'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Red implies urgent, and urgent excludes archived; therefore red excludes archived.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q093', section: 'General Studies II (CSAT)', topic: 'Hindi comprehension', difficulty: 'medium', question: 'For a public-service monitoring task, एक किसान समूह ने एक नई पद्धति को पूरे क्षेत्र में अपनाने से पहले छोटे खेतों पर परीक्षण किया। लाभ दिखा, पर दो मिट्टी प्रकारों में परिणाम अलग थे। समूह ने आगे के विस्तार से पहले मिट्टी के अनुसार निर्देश बनाए।\n\nसमूह ने परीक्षण से क्या सीखा?\n\nThe district note keeps the reporting window and measurement rule unchanged, so the stated difference is directly comparable. Treat the stated observations as the complete evidence for this question and select the strongest supported inference.', options: ['एक ही पद्धति का प्रभाव परिस्थितियों के अनुसार बदल सकता है।', 'परीक्षण के बाद निर्देशों की जरूरत नहीं होती।', 'छोटे परीक्षण कभी उपयोगी नहीं होते।', 'हर मिट्टी में परिणाम समान होते हैं।'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'उत्तर गद्यांश में दिए गए मुख्य कारण और परिणाम के संबंध से निकलता है।', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q094', section: 'General Studies II (CSAT)', topic: 'Hindi comprehension', difficulty: 'medium', question: 'एक बस टर्मिनल ने घंटे-घंटे की कतार मापी। शाम 5 से 7 बजे के बीच प्रतीक्षा सबसे अधिक थी, जबकि बाकी समय सामान्य थी। इसलिए एक अतिरिक्त टिकट खिड़की केवल उन्हीं दो घंटों के लिए खोली गई।\n\nइस निर्णय की विशेषता क्या है?', options: ['सुबह की भीड़ को नजरअंदाज किया गया।', 'अतिरिक्त डेस्क पूरे वर्ष चलाया गया।', 'संसाधन को माँग के समय के अनुसार लगाया गया।', 'भीड़ का मापन निर्णय से असंबंधित था।'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'कतार के समय-आधारित आँकड़ों के आधार पर अतिरिक्त खिड़की केवल अधिक माँग वाले समय में लगाई गई, इसलिए संसाधन का उपयोग माँग के अनुरूप हुआ।', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q095', section: 'General Studies II (CSAT)', topic: 'Comprehension', difficulty: 'medium', question: 'Before the monsoon, a watershed project dug staggered contour trenches on slopes above a reservoir. During heavy rain, the trenches slowed surface flow and trapped visible sediment. Monitoring wells near the trenches also showed higher recharge.\n\nWhy did the upstream works help protect the reservoir?', options: ['They increased the speed of surface runoff.', 'They prevented all rainfall from reaching the reservoir.', 'They slowed runoff and trapped some sediment before it reached the reservoir.', 'They converted groundwater directly into silt.'], correctIndex: 2, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'By slowing runoff, the upstream structures allowed some sediment to settle before the water reached the reservoir, while also encouraging infiltration.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q096', section: 'General Studies II (CSAT)', topic: 'Calendar reasoning', difficulty: 'easy', question: 'While reviewing a district service register, If a review starts on Wednesday, what day of the week will it be 38 days later? Use the stated quantities exactly; no outside assumption is needed.', options: ['Sunday', 'Monday', 'Friday', 'Saturday'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Only the remainder after division by 7 matters. 38 mod 7 = 3; moving 3 days from Wednesday gives Saturday.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q097', section: 'General Studies II (CSAT)', topic: 'Data interpretation', difficulty: 'easy', question: 'In a block-level planning exercise, A four-day service log records 50, 60, 70 and 40 completed applications. What percentage of the four-day total was completed on day 3? Treat every condition in the case as binding.', options: ['31.82', '27.27', '25', '140'], correctIndex: 0, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Four-day total = 220; day 3 share = 70/220×100 = 31.82%.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q098', section: 'General Studies II (CSAT)', topic: 'Mensuration', difficulty: 'medium', question: 'During a public-facility review, A rectangular courtyard is 20 m by 16 m. A uniform path 2 m wide is built outside it. What is the area of the path? The district officer must decide only from these stated facts.', options: ['144', '160', '320', '76'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Outer dimensions are 24 m by 20 m. Path area = outer area − courtyard area = 160 m².', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q099', section: 'General Studies II (CSAT)', topic: 'Averages', difficulty: 'medium', question: 'A district coordination team records the following situation. A public library network has 5 teams averaging 22 completed cases each and 8 teams averaging 30 each. What is the combined average per team? Use the stated quantities exactly; no outside assumption is needed.', options: ['28.92', '26.92', '25.08', '26'], correctIndex: 1, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: 'Use a weighted average: (5×22+8×30)/(13)=26.92.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
  { id: 'b15-001-csat-q100', section: 'General Studies II (CSAT)', topic: 'English usage', difficulty: 'medium', question: 'For a local-service decision note, Fill in the blank: “The report was divided ___ three sections.” Treat every condition in the case as binding.', options: ['in', 'among', 'between', 'into'], correctIndex: 3, answerType: 'mcq', marks: 2.0, negativeMarking: 0.6666666666666666, explanation: '“Divide into” is the standard construction when something is separated into parts.', source: { kind: 'original', reference: 'UPPSC PCS Prelims 2025 GS-II official paper surface', url: 'https://uppsc.up.nic.in/OuterPages/PreQuesPapers.aspx?ID=PrevQues', checkedOn: '2026-09-10' } },
];
